const fbdPanel = (letter, ox, oy, down, up, extra) => {
  const cx = ox + 100, cy = oy + 74;
  const items = [{ label: { x: ox + 18, y: oy + 130, text: letter } }, { rect: { x: cx, y: cy, w: 60, h: 28 } },
    { arrow: { from: [cx, cy], to: [cx, cy - down], label: "mg" } }, { arrow: { from: [cx, cy], to: [cx, cy + up], label: "F_N" } }];
  if (extra) items.push({ arrow: { from: [cx + 42, cy], to: [cx + 42, cy - extra], label: "F_c" } });
  return items;
};
