const E = String.raw;

export default [
  // =========================== 2.7 Kinetic and static friction ===========================
  { id: "p2c-m01", type: "mcq", skill: "u2", topic: "2.7", difficulty: "easy", set: "p2c-s01",
    question: E`What does the $F$-intercept of the line, $F = 6.0$ N, represent?`,
    choices: ["The kinetic friction force on the block", "The maximum static friction force on the block", "The weight of the block", "The net force on the block"],
    why: [E`At $a = 0$ the sliding block moves at constant velocity, so the net force is zero and the pull equals the kinetic friction force: $f_k = 6.0$ N.`,
      E`The block is already sliding, so the friction is kinetic. The maximum static friction applies only to a block that has not yet started to move.`,
      E`The weight is $mg$ and acts vertically. The horizontal pull $F$ is not the weight, and the weight is not found from this graph without the mass.`,
      E`At $F = 6.0$ N the acceleration is zero, so the net force is zero, not $6.0$ N.`], answer: 0 },
  { id: "p2c-m02", type: "mcq", skill: "u2", topic: "2.7", difficulty: "moderate", set: "p2c-s01",
    question: E`What is the mass of the block?`,
    choices: [E`$2.0$ kg`, E`$0.50$ kg`, E`$6.0$ kg`, E`$3.0$ kg`],
    why: [E`For the sliding block, $a = \dfrac{F - f_k}{m}$, so the slope of $a$ versus $F$ is $\dfrac{1}{m}$. The slope is $\dfrac{3.0 - 0}{12 - 6.0} = 0.50\ \text{kg}^{-1}$, so $m = 2.0$ kg.`,
      E`$0.50$ is the slope itself, which equals $1/m$, not $m$.`,
      E`$6.0$ is the friction force in newtons read from the $F$-intercept. It is not a mass.`,
      E`$3.0$ is the size of the $a$-intercept, $f_k/m$ in m/s$^2$. It is not a mass.`], answer: 0 },
  { id: "p2c-m03", type: "mcq", skill: "u2", topic: "2.7", difficulty: "moderate", set: "p2c-s01",
    question: E`What is the coefficient of kinetic friction between the block and the table?`,
    choices: [E`$0.31$`, E`$0.61$`, E`$0.15$`, E`$3.0$`],
    why: [E`From the graph, $f_k = 6.0$ N and $m = 2.0$ kg, so $\mu_k = \dfrac{f_k}{mg} = \dfrac{6.0}{(2.0)(9.8)} = 0.31$.`,
      E`$0.61$ is $\dfrac{6.0}{9.8}$, which leaves out the mass.`,
      E`$0.15$ comes from using the size of the $a$-intercept, $3.0$, as the friction force: $\dfrac{3.0}{(2.0)(9.8)}$.`,
      E`$3.0$ is $\dfrac{6.0}{2.0}$, which leaves out $g$ and gives the deceleration caused by friction, not a coefficient.`], answer: 0 },
  { id: "p2c-m04", type: "mcq", skill: "u2", topic: "2.7", difficulty: "easy", set: "p2c-s02",
    question: E`What is the coefficient of static friction between the block and the board?`,
    choices: [E`$0.62$`, E`$0.53$`, E`$0.85$`, E`$1.6$`],
    why: [E`Just before sliding, $mg\sin\theta = \mu_s\, mg\cos\theta$, so $\mu_s = \tan 32^\circ = 0.62$.`,
      E`$0.53$ is $\sin 32^\circ$, which leaves out the division by the normal force $mg\cos\theta$.`,
      E`$0.85$ is $\cos 32^\circ$, which is the ratio of the normal force to the weight, not of the two components.`,
      E`$1.6$ is $\dfrac{1}{\tan 32^\circ}$, from dividing the components in the wrong order.`], answer: 0 },
  { id: "p2c-m05", type: "mcq", skill: "u2", topic: "2.7", difficulty: "moderate", set: "p2c-s02",
    question: E`The experiment is repeated with a block of twice the mass made of the same material. The angle at which this block begins to slide is`,
    choices: [E`unchanged, because $\mu_s$ does not depend on the mass`, E`smaller, because the weight component along the board doubles`, E`larger, because the normal force and the maximum friction force double`, E`smaller, because the coefficient decreases as the weight increases`],
    why: [E`Slipping starts when $mg\sin\theta = \mu_s\, mg\cos\theta$. The mass cancels, so $\tan\theta = \mu_s$ gives the same angle, $32^\circ$.`,
      E`The weight component along the board does double, but the maximum static friction force doubles too, so the two still balance at the same angle.`,
      E`The normal force and the maximum friction force do double, but the weight component along the board doubles as well, so the angle does not change.`,
      E`The coefficient depends on the two surfaces, not on the weight of the block.`], answer: 0 },
  { id: "p2c-m06", type: "mcq", skill: "u2", topic: "2.7", difficulty: "moderate", set: "p2c-s03",
    question: E`The truck speeds up from rest toward the front at $2.0$ m/s$^2$. What is the friction force on the crate?`,
    choices: [E`$80$ N forward`, E`$80$ N backward`, E`$196$ N forward`, E`$392$ N forward`],
    why: [E`Friction from the bed is the only horizontal force on the crate, and the crate accelerates with the truck: $f = ma = (40)(2.0) = 80$ N, forward.`,
      E`The magnitude is right, but the crate accelerates forward, so the net force, which is the friction force, points toward the front.`,
      E`$196$ N is the maximum static friction, $\mu_s mg = (0.50)(40)(9.8)$. The crate is not on the verge of sliding, so friction is only as large as needed.`,
      E`$392$ N is the weight of the crate, which is a vertical force and is not the friction force.`], answer: 0 },
  { id: "p2c-m07", type: "mcq", skill: "u2", topic: "2.7", difficulty: "difficult", set: "p2c-s03",
    question: E`The truck travels at $15$ m/s and brakes to a stop. What is the shortest distance in which the truck can stop without the crate sliding?`,
    choices: [E`$23$ m`, E`$46$ m`, E`$11$ m`, E`$0.57$ m`],
    why: [E`The crate decelerates with the truck, and the most friction can supply is $\mu_s mg$, so $a_{max} = \mu_s g = 4.9$ m/s$^2$. Then $d = \dfrac{v^2}{2a} = \dfrac{15^2}{2(4.9)} = 23$ m.`,
      E`$46$ m is $\dfrac{v^2}{a}$, which leaves out the factor $2$ in $v^2 = 2ad$.`,
      E`$11$ m uses $a = g$, which leaves out $\mu_s$.`,
      E`$0.57$ m uses the maximum friction force, $196$ N, as the acceleration.`], answer: 0 },
  { id: "p2c-m08", type: "mcq", skill: "u2", topic: "2.7", difficulty: "moderate", set: "p2c-s04",
    question: E`What is the magnitude of the normal force exerted by the floor on the crate?`,
    choices: [E`$156$ N`, E`$196$ N`, E`$236$ N`, E`$69$ N`],
    why: [E`The vertical forces balance: $F_N + T\sin 30^\circ = mg$, so $F_N = 196 - 80\sin 30^\circ = 196 - 40 = 156$ N.`,
      E`$196$ N is $mg$. The upward part of the rope tension carries some of the weight, so the floor pushes with less than $mg$.`,
      E`$236$ N adds the vertical part of the tension, but the rope pulls up and reduces the normal force.`,
      E`$69$ N is $T\cos 30^\circ$, the horizontal part of the tension, which is not a vertical force.`], answer: 0 },
  { id: "p2c-m09", type: "mcq", skill: "u2", topic: "2.7", difficulty: "difficult", set: "p2c-s04",
    question: E`What is the coefficient of kinetic friction between the crate and the floor?`,
    choices: [E`$0.44$`, E`$0.35$`, E`$0.51$`, E`$0.26$`],
    why: [E`At constant velocity, $f_k = T\cos 30^\circ = 69.3$ N, and $F_N = 156$ N from the vertical balance. Then $\mu_k = \dfrac{f_k}{F_N} = \dfrac{69.3}{156} = 0.44$.`,
      E`$0.35$ uses $mg = 196$ N as the normal force, which ignores the upward pull of the rope.`,
      E`$0.51$ uses the full tension, $80$ N, as the friction force instead of its horizontal part.`,
      E`$0.26$ uses $T\sin 30^\circ = 40$ N, the vertical part of the tension, as the friction force.`], answer: 0 },
  { id: "p2c-m10", type: "mcq", skill: "u2", topic: "2.7", difficulty: "easy",
    question: E`A wooden brick slides at the same speed across a level table, first resting on its largest face and then on its smallest face. How does the kinetic friction force on the brick compare in the two cases?`,
    choices: ["It is the same, because the normal force and surfaces are unchanged", "It is larger on the largest face, because more surface area is in contact", "It is larger on the smallest face, because the weight is spread over a smaller area", "It is smaller on the largest face, because the pressure on the table is lower"],
    why: [E`Kinetic friction is $f_k = \mu_k F_N$. The normal force is $mg$ in both cases and the surfaces are the same, so the friction force is the same.`,
      E`The friction force does not depend on the contact area, so more area in contact does not mean more friction.`,
      E`A smaller area raises the pressure but not the friction force, which depends on $\mu_k$ and $F_N$ only.`,
      E`The lower pressure does not lower the friction force. The normal force and $\mu_k$ are unchanged.`], answer: 0 },
  { id: "p2c-m11", type: "mcq", skill: "u2", topic: "2.7", difficulty: "moderate",
    question: E`A puck slides on a level sheet of ice. Its initial speed is $6.0$ m/s, and it comes to rest after sliding $18$ m. What is the coefficient of kinetic friction between the puck and the ice?`,
    choices: [E`$0.10$`, E`$0.20$`, E`$1.0$`, E`$0.034$`],
    why: [E`Friction is the only horizontal force, so $a = \mu_k g$. From $v^2 = 2ad$, $a = \dfrac{6.0^2}{2(18)} = 1.0$ m/s$^2$, and $\mu_k = \dfrac{a}{g} = \dfrac{1.0}{9.8} = 0.10$.`,
      E`$0.20$ uses $a = \dfrac{v^2}{d}$, which leaves out the factor $2$.`,
      E`$1.0$ is the deceleration in m/s$^2$. The coefficient is $a$ divided by $g$.`,
      E`$0.034$ divides $v$, not $v^2$, by $gd$.`], answer: 0 },
  { id: "p2c-m12", type: "mcq", skill: "u2", topic: "2.7", difficulty: "moderate",
    question: E`A car speeds up along a level road, and its tires roll without skidding. Which statement describes the horizontal force of the road on the tires that accelerates the car?`,
    choices: ["Forward static friction, because the tire does not slip", "Forward kinetic friction, because the tire rubs against the road", "Backward static friction, because friction always opposes the motion of the car", "No friction force, because the engine alone pushes the car forward"],
    why: [E`The patch of tire in contact with the road is momentarily at rest relative to the road, so the friction is static. It points forward, and it is the external horizontal force that accelerates the car.`,
      E`The tires do not skid, so the contact patch does not slide on the road and the friction is not kinetic.`,
      E`Friction opposes sliding of the surfaces in contact, not the motion of the car. The tire pushes backward on the road, so the road pushes the tire forward.`,
      E`The engine's force on the car is internal. Only an external force, here friction from the road, can accelerate the car.`], answer: 0 },
  // =========================== 2.8 Spring forces ===========================
  { id: "p2c-m13", type: "mcq", skill: "u2", topic: "2.8", difficulty: "moderate", set: "p2c-s05",
    question: E`What is the spring constant of the spring?`,
    choices: [E`$50$ N/m`, E`$17$ N/m`, E`$25$ N/m`, E`$0.020$ N/m`],
    why: [E`The spring constant is the slope of $F$ versus the extension, and the extension changes by the same amount as the length. The slope is $\dfrac{10 - 5.0}{0.40 - 0.30} = 50$ N/m.`,
      E`$17$ N/m is $\dfrac{5.0}{0.30}$, the force divided by the total length at one point. The spring force depends on the extension, not on the total length.`,
      E`$25$ N/m is $\dfrac{10}{0.40}$, the same mistake at a second point.`,
      E`$0.020$ N/m is the reciprocal of the slope, $\dfrac{\Delta L}{\Delta F}$.`], answer: 0 },
  { id: "p2c-m14", type: "mcq", skill: "u2", topic: "2.8", difficulty: "easy", set: "p2c-s05",
    question: E`What force is needed to hold the spring at a length of $0.26$ m?`,
    choices: [E`$3.0$ N`, E`$13$ N`, E`$4.3$ N`, E`$300$ N`],
    why: [E`The relaxed length is $0.20$ m, so the extension is $0.06$ m and $F = kx = (50)(0.06) = 3.0$ N.`,
      E`$13$ N is $k$ times the total length, $(50)(0.26)$. The extension from the relaxed length is what counts.`,
      E`$4.3$ N scales the force at $0.30$ m in proportion to the length, but the force is proportional to the extension.`,
      E`$300$ N puts the extension in centimeters, $(50)(6)$, into a formula that needs meters.`], answer: 0 },
  { id: "p2c-m15", type: "mcq", skill: "u2", topic: "2.8", difficulty: "easy", set: "p2c-s06",
    question: E`What is the friction force on the block?`,
    choices: [E`$8.0$ N away from the wall`, E`$8.0$ N toward the wall`, E`$800$ N away from the wall`, E`$20$ N away from the wall`],
    why: [E`The spring pulls the block toward the wall with $kx = (200)(0.040) = 8.0$ N. The block is at rest, so static friction balances it: $8.0$ N, away from the wall.`,
      E`The magnitude is right, but friction must oppose the spring force, which points toward the wall.`,
      E`$800$ N uses the extension in centimeters, $(200)(4.0)$.`,
      E`$20$ N is close to the weight of the block, $19.6$ N. Static friction equals the force it balances, not the weight.`], answer: 0 },
  { id: "p2c-m16", type: "mcq", skill: "u2", topic: "2.8", difficulty: "moderate", set: "p2c-s06",
    question: E`The spring is now slowly stretched further. What is the largest extension of the spring for which the block stays at rest?`,
    choices: [E`$4.9$ cm`, E`$9.8$ cm`, E`$0.49$ cm`, E`$49$ cm`],
    why: [E`The block begins to slide when $kx = \mu_s mg$, so $x = \dfrac{(0.50)(2.0)(9.8)}{200} = 0.049$ m $= 4.9$ cm.`,
      E`$9.8$ cm is $\dfrac{mg}{k}$, which leaves out $\mu_s$.`,
      E`$0.49$ cm moves the decimal point the wrong way when converting $0.049$ m to centimeters.`,
      E`$49$ cm multiplies $0.049$ m by $1000$ instead of $100$.`], answer: 0 },
  { id: "p2c-m17", type: "mcq", skill: "u2", topic: "2.8", difficulty: "moderate", set: "p2c-s07",
    question: E`Which graph correctly shows the force that the spring exerts on the block?`,
    choices: ["Graph C", "Graph A", "Graph B", "Graph D"],
    why: [E`Hooke's law gives $F_x = -kx$: a straight line through the origin whose negative slope shows that the force opposes the displacement. Graph C shows this.`,
      E`Graph A has a positive slope, so the force would point away from the relaxed position and the spring would push the block farther.`,
      E`Graph B has a nonzero force at $x = 0$, but the spring exerts no force when it is relaxed.`,
      E`Graph D is not a straight line, so the force would not be proportional to $x$, and it points the same way on both sides of the origin. The spring force reverses direction when the block crosses $x = 0$.`], answer: 0 },
  { id: "p2c-m18", type: "mcq", skill: "u2", topic: "2.8", difficulty: "moderate",
    question: E`A block hangs at rest from a vertical spring of negligible mass and stretches it $6.0$ cm from its relaxed length. When an additional mass of $0.30$ kg is added to the block, the total stretch becomes $9.0$ cm. What is the spring constant?`,
    choices: [E`$98$ N/m`, E`$33$ N/m`, E`$49$ N/m`, E`$0.98$ N/m`],
    why: [E`The extra weight produces the extra stretch: $k = \dfrac{\Delta F}{\Delta x} = \dfrac{(0.30)(9.8)}{0.030} = 98$ N/m.`,
      E`$33$ N/m divides the extra weight by the total stretch, $0.090$ m, instead of the added stretch.`,
      E`$49$ N/m divides the extra weight by the first stretch, $0.060$ m.`,
      E`$0.98$ N/m divides by the added stretch in centimeters, $3.0$, instead of $0.030$ m.`], answer: 0 },
  // =========================== 2.9 Circular motion ===========================
  { id: "p2c-m19", type: "mcq", skill: "u2", topic: "2.9", difficulty: "moderate", set: "p2c-s08",
    question: E`What is the speed of the puck?`,
    choices: [E`$3.4$ m/s`, E`$1.1$ m/s`, E`$12$ m/s`, E`$2.0$ m/s`],
    why: [E`The string tension equals the weight of the hanging mass, $T = Mg$, and it is the only horizontal force on the puck, so $Mg = \dfrac{mv^2}{r}$. Then $v = \sqrt{\dfrac{Mgr}{m}} = \sqrt{\dfrac{(0.60)(9.8)(0.40)}{0.20}} = 3.4$ m/s.`,
      E`$1.1$ m/s swaps the two masses and uses $\sqrt{mgr/M}$.`,
      E`$12$ m/s is $v^2$. The square root was not taken.`,
      E`$2.0$ m/s uses the puck's weight, $mg$, as the tension.`], answer: 0 },
  { id: "p2c-m20", type: "mcq", skill: "u2", topic: "2.9", difficulty: "easy", set: "p2c-s08",
    question: E`The $0.60$ kg hanging mass is replaced by a $2.4$ kg mass, and the puck moves in a circle of the same radius at a steady speed. The speed of the puck was $v$. The new speed is`,
    choices: [E`$2v$`, E`$4v$`, E`$v/2$`, E`$v$`],
    why: [E`The tension, which is the net force on the puck, becomes $4$ times larger. Since $T = \dfrac{mv^2}{r}$ with $m$ and $r$ unchanged, $v \propto \sqrt{T}$, so the speed becomes $2v$.`,
      E`$4v$ treats the speed as proportional to the force, but the force is proportional to $v^2$.`,
      E`$v/2$ inverts the relationship. A larger inward force needs a larger speed at the same radius.`,
      E`The puck's mass and the radius are unchanged, but the force changed, so the speed changes.`], answer: 0 },
  { id: "p2c-m21", type: "mcq", skill: "u2", topic: "2.9", difficulty: "moderate", set: "p2c-s09",
    question: E`What is the magnitude of the normal force of the road on the car at the top of the hill?`,
    choices: [E`$7.4 \times 10^{3}$ N`, E`$1.2 \times 10^{4}$ N`, E`$1.6 \times 10^{4}$ N`, E`$4.3 \times 10^{3}$ N`],
    why: [E`At the top, the center of the circle is below the car, so $mg - F_N = \dfrac{mv^2}{r}$. Then $F_N = m\left(g - \dfrac{v^2}{r}\right) = 1200\left(9.8 - \dfrac{144}{40}\right) = 7.4 \times 10^{3}$ N.`,
      E`$1.2 \times 10^{4}$ N is $mg$. The car has a downward acceleration at the top, so the normal force is less than the weight.`,
      E`$1.6 \times 10^{4}$ N is $m\left(g + \dfrac{v^2}{r}\right)$, which has the sign for the bottom of a dip.`,
      E`$4.3 \times 10^{3}$ N is $\dfrac{mv^2}{r}$, which is the net force and leaves out the weight.`], answer: 0 },
  { id: "p2c-m22", type: "mcq", skill: "u2", topic: "2.9", difficulty: "difficult", set: "p2c-s09",
    question: E`What is the greatest speed at which the car can cross the top of the hill and stay in contact with the road?`,
    choices: [E`$20$ m/s`, E`$390$ m/s`, E`$6.3$ m/s`, E`$28$ m/s`],
    why: [E`The car loses contact when $F_N = 0$. Then gravity alone supplies the force toward the center, $mg = \dfrac{mv^2}{r}$, so $v = \sqrt{gr} = \sqrt{(9.8)(40)} = 20$ m/s.`,
      E`$390$ m/s is $gr$, the value of $v^2$, without the square root.`,
      E`$6.3$ m/s is $\sqrt{r}$, which leaves out $g$.`,
      E`$28$ m/s is $\sqrt{2gr}$, which borrows the factor $2$ from $v^2 = 2ad$ and does not belong here.`], answer: 0 },
  { id: "p2c-m23", type: "mcq", skill: "u2", topic: "2.9", difficulty: "moderate", set: "p2c-s10",
    question: E`Which free-body diagram shows the forces on the car at the top of the hill?`,
    choices: ["Diagram A", "Diagram B", "Diagram C", "Diagram D"],
    why: [E`At the top, the acceleration points down toward the center, so the net force points down: the weight is larger than the normal force. Diagram A shows only the two real forces, with the weight longer.`,
      E`Diagram B has the normal force larger than the weight, which would give a net force upward, away from the center of the circle.`,
      E`Diagram C has equal forces, so the net force would be zero, but the car has a nonzero acceleration toward the center.`,
      E`Diagram D adds a centripetal force. The net force toward the center is the result of the weight and the normal force. It is not a separate force from another object.`], answer: 0 },
  { id: "p2c-m24", type: "mcq", skill: "u2", topic: "2.9", difficulty: "difficult", set: "p2c-s11",
    question: E`What is the smallest coefficient of static friction between the rider and the wall that keeps the rider from sliding down?`,
    choices: [E`$0.40$`, E`$2.5$`, E`$0.79$`, E`$0.16$`],
    why: [E`The wall's normal force supplies the center-directed force, $F_N = \dfrac{mv^2}{r}$, with $v = \dfrac{2\pi r}{T} = 7.85$ m/s, so $\dfrac{v^2}{r} = 24.7$ m/s$^2$. Friction must support the weight: $\mu_s F_N \geq mg$, so $\mu_s \geq \dfrac{g}{v^2/r} = \dfrac{9.8}{24.7} = 0.40$.`,
      E`$2.5$ is $\dfrac{v^2/r}{g}$, the inverse of the ratio needed.`,
      E`$0.79$ treats $2.5$ m as the diameter, so the radius used is $1.25$ m.`,
      E`$0.16$ uses $v^2$ in place of $\dfrac{v^2}{r}$ and leaves out the division by the radius.`], answer: 0 },
  { id: "p2c-m25", type: "mcq", skill: "u2", topic: "2.9", difficulty: "moderate", set: "p2c-s11",
    question: E`The cylinder is now spun faster, and the rider still does not slide. Compared with before, the normal force and the friction force on the rider are`,
    choices: ["larger normal force, same friction force", "larger normal force, larger friction force", "larger normal force, smaller friction force", "same normal force, greater friction force"],
    why: [E`The normal force provides the center-directed force $\dfrac{mv^2}{r}$, which increases with speed. The rider is not accelerating vertically, so the friction force still equals the weight.`,
      E`The friction force must equal the weight to keep the rider from sliding. It does not grow with the normal force, since the rider is not on the verge of slipping.`,
      E`The friction force must still balance the weight, so it cannot decrease.`,
      E`The normal force must increase because the center-directed force $\dfrac{mv^2}{r}$ grows with speed.`], answer: 0 },
  { id: "p2c-m26", type: "mcq", skill: "u2", topic: "2.9", difficulty: "moderate", set: "p2c-s12",
    question: E`What is the coefficient of static friction between the coin and the turntable?`,
    choices: [E`$0.40$`, E`$0.010$`, E`$4.0$`, E`$39$`],
    why: [E`At the point of sliding, $\mu_s mg = \dfrac{mv^2}{r}$ with $v = \dfrac{2\pi r}{T}$, so $\mu_s = \dfrac{4\pi^2 r}{gT^2} = \dfrac{4\pi^2(0.100)}{(9.8)(1.00)^2} = 0.40$.`,
      E`$0.010$ leaves out the factor $2\pi$ in the speed, using $v = \dfrac{r}{T}$.`,
      E`$4.0$ leaves out the radius, using $\dfrac{4\pi^2}{gT^2}$.`,
      E`$39$ is $\dfrac{4\pi^2 r}{T^2}$ times $g$ instead of divided by $g$.`], answer: 0 },
  { id: "p2c-m27", type: "mcq", skill: "u2", topic: "2.9", difficulty: "moderate", set: "p2c-s12",
    question: E`A second identical coin is placed at $r = 0.200$ m on the same turntable, which is sped up from rest in the same way. At what period does this coin begin to slide?`,
    choices: [E`$1.4$ s`, E`$0.71$ s`, E`$2.0$ s`, E`$0.50$ s`],
    why: [E`Sliding begins when $\dfrac{4\pi^2 r}{T^2} = \mu_s g$. The right side is the same for both coins, so $T \propto \sqrt{r}$ and $T = 1.00\sqrt{2} = 1.4$ s. The outer coin slides first, at a longer period.`,
      E`$0.71$ s is $\dfrac{1.00}{\sqrt{2}}$, which reverses the relationship. The outer coin needs a smaller period to stay on, not a larger one.`,
      E`$2.0$ s takes the period to be proportional to the radius.`,
      E`$0.50$ s takes the period to be inversely proportional to the radius.`], answer: 0 },
  { id: "p2c-m28", type: "mcq", skill: "u2", topic: "2.9", difficulty: "moderate", set: "p2c-s13",
    question: E`At the bottom of the loop, the airplane's speed is $40$ m/s. What is the magnitude of the force of the seat on the pilot?`,
    choices: [E`$2.1 \times 10^{3}$ N`, E`$7.8 \times 10^{2}$ N`, E`$1.3 \times 10^{3}$ N`, E`$5.0 \times 10^{2}$ N`],
    why: [E`At the bottom, the center is above the pilot, so $F_N - mg = \dfrac{mv^2}{r}$. Then $F_N = m\left(g + \dfrac{v^2}{r}\right) = 80\left(9.8 + 16\right) = 2.1 \times 10^{3}$ N.`,
      E`$7.8 \times 10^{2}$ N is the weight, $mg$. The pilot has an upward acceleration at the bottom, so the seat pushes with more than the weight.`,
      E`$1.3 \times 10^{3}$ N is $\dfrac{mv^2}{r}$, the net force, with the weight left out.`,
      E`$5.0 \times 10^{2}$ N is $m\left(\dfrac{v^2}{r} - g\right)$, which has the sign for the top of the loop.`], answer: 0 },
  { id: "p2c-m29", type: "mcq", skill: "u2", topic: "2.9", difficulty: "difficult", set: "p2c-s13",
    question: E`At the top of the loop, at what speed is the force of the seat on the pilot equal to the pilot's weight?`,
    choices: [E`$44$ m/s`, E`$31$ m/s`, E`$22$ m/s`, E`$63$ m/s`],
    why: [E`At the top, the seat and gravity both point down, toward the center: $F_N + mg = \dfrac{mv^2}{r}$. With $F_N = mg$, $2g = \dfrac{v^2}{r}$, so $v = \sqrt{2gr} = \sqrt{2(9.8)(100)} = 44$ m/s.`,
      E`$31$ m/s is $\sqrt{gr}$, which is the speed at which the seat force is zero.`,
      E`$22$ m/s is $\sqrt{gr/2}$, which puts the factor of $2$ in the wrong place.`,
      E`$63$ m/s uses $200$ m, the diameter, in place of the radius.`], answer: 0 },
  { id: "p2c-m30", type: "mcq", skill: "u2", topic: "2.9", difficulty: "moderate", set: "p2c-s14",
    question: E`Which graph shows how the centripetal acceleration depends on the distance from the center?`,
    choices: ["Graph C", "Graph A", "Graph B", "Graph D"],
    why: [E`All the objects have the same angular speed, so $a_c = \omega^2 r$. The acceleration is proportional to $r$, a straight line through the origin. Graph C shows this.`,
      E`Graph A shows $a_c \propto \dfrac{1}{r}$, which holds for objects with the same speed $v$, not the same angular speed.`,
      E`Graph B shows $a_c \propto r^2$, which has a squared dependence that does not appear in $a_c = \omega^2 r$.`,
      E`Graph D shows a constant $a_c$, but objects farther out move faster along larger circles and need a larger acceleration.`], answer: 0 },
  { id: "p2c-m31", type: "mcq", skill: "u2", topic: "2.9", difficulty: "moderate", set: "p2c-s15",
    question: E`Which graph of the data gives a straight line?`,
    choices: ["$T$ versus $v^2$", "$T$ versus $v$", "$T$ versus $\\dfrac{1}{v}$", "$T$ versus $\\sqrt{v}$"],
    why: [E`The tension is the net force toward the center: $T = \dfrac{m}{r}v^2$. So $T$ is a linear function of $v^2$, and the data confirm this: $T$ is $0.40v^2$ for every row.`,
      E`$T$ versus $v$ gives a curve, since $T$ grows with the square of $v$.`,
      E`$T$ versus $\dfrac{1}{v}$ gives a decreasing curve, but $T$ increases with $v$.`,
      E`$T$ versus $\sqrt{v}$ would be a curve that rises more slowly than $T \propto v$.`], answer: 0 },
  { id: "p2c-m32", type: "mcq", skill: "u2", topic: "2.9", difficulty: "moderate", set: "p2c-s15",
    question: E`What is the mass of the puck?`,
    choices: [E`$0.20$ kg`, E`$0.40$ kg`, E`$0.80$ kg`, E`$0.10$ kg`],
    why: [E`From $T = \dfrac{m}{r}v^2$, the slope of $T$ versus $v^2$ is $\dfrac{m}{r} = 0.40$ N/(m/s)$^2$, so $m = (0.40)(0.50) = 0.20$ kg.`,
      E`$0.40$ is the slope itself, $\dfrac{m}{r}$. The mass is the slope times $r$.`,
      E`$0.80$ divides the slope by $r$ instead of multiplying.`,
      E`$0.10$ multiplies the slope by $r^2$.`], answer: 0 },
  { id: "p2c-m33", type: "mcq", skill: "u2", topic: "2.9", difficulty: "easy", set: "p2c-s16",
    question: E`How does the speed of the block of mass $2m$ compare with the speed of the block of mass $m$?`,
    choices: [E`$v_{2m} = 2v_m$`, E`$v_{2m} = v_m$`, E`$v_{2m} = \dfrac{v_m}{2}$`, E`$v_{2m} = 4v_m$`],
    why: [E`Both blocks make one revolution in the same time, so $v = \dfrac{2\pi r}{T}$ is proportional to the radius. The block at $2r$ moves twice as fast.`,
      E`The blocks have the same angular speed, not the same linear speed. The block on the larger circle covers a larger distance in the same time.`,
      E`The block farther from the center travels a longer path in the same period, so it moves faster, not slower.`,
      E`The speed is proportional to $r$, not $r^2$, so doubling the radius doubles the speed.`], answer: 0 },
  { id: "p2c-m34", type: "mcq", skill: "u2", topic: "2.9", difficulty: "moderate", set: "p2c-s16",
    question: E`How does the net force on the block of mass $2m$ compare with the net force on the block of mass $m$?`,
    choices: [E`$F_{2m} = 4F_m$`, E`$F_{2m} = 2F_m$`, E`$F_{2m} = 8F_m$`, E`$F_{2m} = F_m$`],
    why: [E`The net force is $m\omega^2 r$. The mass doubles and the radius doubles with the same $\omega$, so the force becomes $2 \times 2 = 4$ times as large.`,
      E`$2F_m$ accounts for the mass but not for the larger radius.`,
      E`$8F_m$ multiplies the mass factor by $v^2$ ($\times 4$) and leaves out the division by $r$ in $\dfrac{mv^2}{r}$.`,
      E`The two blocks have different masses and radii, so the forces are different.`], answer: 0 },
  { id: "p2c-m35", type: "mcq", skill: "u2", topic: "2.9", difficulty: "easy",
    question: E`A ball moves at constant speed $v$ in a horizontal circle of radius $r$ on a string, and the tension is $F$. The string is now lengthened so that the ball moves at the same speed in a circle of radius $2r$. The tension is now`,
    choices: [E`$\dfrac{F}{2}$`, E`$2F$`, E`$\dfrac{F}{4}$`, E`$F$`],
    why: [E`The tension supplies the force toward the center, $F = \dfrac{mv^2}{r}$. At the same speed, doubling $r$ halves the force: $\dfrac{F}{2}$.`,
      E`$2F$ takes the force to be proportional to $r$.`,
      E`$\dfrac{F}{4}$ takes the force to depend on $\dfrac{1}{r^2}$.`,
      E`The radius changed while the speed and mass did not, so the force changes.`], answer: 0 },
  { id: "p2c-m36", type: "mcq", skill: "u2", topic: "2.9", difficulty: "easy",
    question: E`A puck moves at constant speed in a horizontal circle on a frictionless table, attached to a string that is anchored at the center. The string breaks. Which statement describes the motion of the puck after the string breaks, as seen from above?`,
    choices: ["It moves along the tangent in a straight line, since no force acts", "It moves in a straight line directly away from the center, because the puck is thrown outward", "It continues to move in the circle for a short time, because it has inertia", "It moves along a curve that spirals outward, because the outward force remains"],
    why: [E`The string was the only horizontal force. Once it breaks, the net force is zero, so the puck keeps its velocity at that instant, which is tangent to the circle.`,
      E`The velocity at the instant of the break is tangent to the circle, not radial, and no outward force acts on the puck.`,
      E`Inertia makes the puck keep moving in a straight line. Without a force toward the center it cannot keep circling.`,
      E`There is no outward force on the puck at any time, so there is no outward spiral.`], answer: 0 },
  { id: "p2c-m37", type: "mcq", skill: "u2", topic: "2.9", difficulty: "easy",
    question: E`A car turns sharply to the left, and a passenger on a smooth seat slides toward the right door. Which statement gives the correct reason?`,
    choices: ["The passenger tends to keep moving straight while the car turns", "A force directed outward pushes the passenger toward the right door", "The seat exerts a force on the passenger that is directed toward the right door", "The force of the car on the passenger is larger than the force of the passenger on the car"],
    why: [E`With little friction from the seat, no force turns the passenger left, so the passenger's velocity stays the same while the car turns left. Relative to the car, the passenger slides right.`,
      E`There is no outward force on the passenger. An outward force would make the net force point away from the center of the turn.`,
      E`A smooth seat exerts little friction, and any friction from the seat would point toward the left, the center of the turn.`,
      E`The two forces in an action-reaction pair always have equal magnitudes.`], answer: 0 },
  { id: "p2c-m38", type: "mcq", skill: "u2", topic: "2.9", difficulty: "easy",
    question: E`A runner moves at a constant speed of $5.0$ m/s around a curve of radius $25$ m. What is the magnitude of the runner's centripetal acceleration?`,
    choices: [E`$1.0$ m/s$^2$`, E`$0.20$ m/s$^2$`, E`$25$ m/s$^2$`, E`$0.50$ m/s$^2$`],
    why: [E`$a_c = \dfrac{v^2}{r} = \dfrac{5.0^2}{25} = 1.0$ m/s$^2$.`,
      E`$0.20$ m/s$^2$ is $\dfrac{v}{r}$, which does not square the speed.`,
      E`$25$ m/s$^2$ is $v^2$, which leaves out the division by $r$.`,
      E`$0.50$ m/s$^2$ is $\dfrac{v^2}{2r}$, which has an extra factor of $2$ in the denominator.`], answer: 0 },
  { id: "p2c-m39", type: "mcq", skill: "u2", topic: "2.9", difficulty: "moderate",
    question: E`A $0.50$ kg ball on a string moves in a horizontal circle of radius $0.60$ m and makes $5.0$ revolutions in $4.0$ s. What is the magnitude of the net force on the ball?`,
    choices: [E`$19$ N`, E`$0.74$ N`, E`$0.47$ N`, E`$9.3$ N`],
    why: [E`The period is $T = \dfrac{4.0}{5.0} = 0.80$ s, so $v = \dfrac{2\pi r}{T} = 4.71$ m/s. Then $F = \dfrac{mv^2}{r} = \dfrac{(0.50)(4.71)^2}{0.60} = 19$ N.`,
      E`$0.74$ N takes the period to be $4.0$ s, the total time, instead of the time for one revolution.`,
      E`$0.47$ N leaves out the factor $2\pi$ in the speed.`,
      E`$9.3$ N takes $0.60$ m to be the diameter, so the radius used is $0.30$ m.`], answer: 0 },
  { id: "p2c-m40", type: "mcq", skill: "u2", topic: "2.9", difficulty: "moderate",
    question: E`Satellite A orbits Earth in a circular orbit of radius $r$ at speed $v$. Satellite B has the same mass and orbits in a circular orbit of radius $4r$. The speed of satellite B is`,
    choices: [E`$\dfrac{v}{2}$`, E`$\dfrac{v}{4}$`, E`$\dfrac{v}{16}$`, E`$2v$`],
    why: [E`Gravity supplies the force toward the center: $\dfrac{GMm}{r^2} = \dfrac{mv^2}{r}$, so $v = \sqrt{\dfrac{GM}{r}}$. At $4r$ the speed is $\dfrac{1}{\sqrt{4}} = \dfrac{1}{2}$ as large.`,
      E`$\dfrac{v}{4}$ takes the speed to be proportional to $\dfrac{1}{r}$.`,
      E`$\dfrac{v}{16}$ takes the speed to be proportional to the gravitational force, $\dfrac{1}{r^2}$.`,
      E`$2v$ takes the speed to be proportional to $\sqrt{r}$, which would put the faster satellite in the larger orbit.`], answer: 0 },
  { id: "p2c-m41", type: "mcq", skill: "u2", topic: "2.9", difficulty: "moderate",
    question: E`A centrifuge spins a sample at $3000$ revolutions per minute at a distance of $0.10$ m from the axis. What is the magnitude of the sample's centripetal acceleration?`,
    choices: [E`$9.9 \times 10^{3}$ m/s$^2$`, E`$9.0 \times 10^{5}$ m/s$^2$`, E`$2.5 \times 10^{2}$ m/s$^2$`, E`$3.6 \times 10^{7}$ m/s$^2$`],
    why: [E`$\omega = (3000)\dfrac{2\pi}{60} = 314$ rad/s, so $a_c = \omega^2 r = (314)^2(0.10) = 9.9 \times 10^{3}$ m/s$^2$.`,
      E`$9.0 \times 10^{5}$ m/s$^2$ uses $3000$ as the angular speed in rad/s.`,
      E`$2.5 \times 10^{2}$ m/s$^2$ converts to revolutions per second, $50$, and leaves out the $2\pi$.`,
      E`$3.6 \times 10^{7}$ m/s$^2$ multiplies by $2\pi$ but does not divide by $60$ s per minute.`], answer: 0 },
  // =========================== Free response (EDA, 10 points) ===========================
  { id: "p2c-f1a", type: "frq", skill: "u2", topic: "2.9", set: "p2c-s17", part: "(a)",
    prompt: E`The student plans to collect data on how the distance $r$ depends on the angular speed $\omega$. Describe an experimental procedure to collect these data. Include the independent and dependent variables, and say how each is measured, naming the measuring instruments.`,
    rows: [{ name: "Independent variable", earns: E`Identifies $\omega$ (or the period or frequency of rotation) as the quantity that is changed, and says how it is measured: times a number of complete rotations with a stopwatch and divides to get the period, or uses a rotation sensor.` },
      { name: "Dependent variable", earns: E`Identifies $r$ as the quantity that responds and measures it with a meter stick or ruler along the rod, from the axle to the block, at several different values of $\omega$.` }],
    solution: E`Spin the rod at a steady rate and time $10$ complete rotations with a stopwatch. The period is the time divided by $10$, and $\omega = \dfrac{2\pi}{T}$. This is the independent variable. When the block settles at a steady position, read $r$ with a meter stick along the rod. This is the dependent variable. Repeat at five or more different rotation rates.` },
  { id: "p2c-f1b", type: "frq", skill: "u2", topic: "2.9", set: "p2c-s17", part: "(b)",
    prompt: E`Derive an equation that relates $r$, $\omega$, $m$, $k$, and $L_0$. Begin with Newton's second law applied to the block.`,
    rows: [{ name: "Force on the block", earns: E`States that the spring force $k(r - L_0)$ is the only horizontal force on the block and is the net force, directed toward the axle.` },
      { name: "Second law", earns: E`Sets the net force equal to $m\omega^2 r$ (or $\dfrac{mv^2}{r}$ with $v = \omega r$): $k(r - L_0) = m\omega^2 r$.` }],
    solution: E`The rod is smooth, so the spring is the only horizontal force on the block. Its extension is $r - L_0$. The block moves in a circle of radius $r$, so $\sum F = ma_c$ gives $$k(r - L_0) = m\omega^2 r.$$` },
  { id: "p2c-f1ci", type: "frq", skill: "u2", topic: "2.9", set: "p2c-s17", part: "(c)(i)",
    prompt: E`The student plans to graph the data so that the slope of a straight line can be used to find $k$. Which quantities should be plotted on the vertical and horizontal axes? Use the equation from part (b) to explain how the spring constant can be found from the slope of the line.`,
    rows: [{ name: "Quantities", earns: E`Plots $\dfrac{1}{r}$ on one axis and $\omega^2$ on the other (either axis may be used for either quantity if the slope analysis is consistent).` },
      { name: "Linear form", earns: E`Rearranges the equation from part (b) into a linear form, for example $\dfrac{1}{r} = \dfrac{1}{L_0} - \dfrac{m}{kL_0}\,\omega^2$.` },
      { name: "Slope", earns: E`States that the slope of the graph of $\dfrac{1}{r}$ versus $\omega^2$ is $-\dfrac{m}{kL_0}$ (its magnitude is $\dfrac{m}{kL_0}$), and says how to use it to find $k$.` }],
    solution: E`Divide $k(r - L_0) = m\omega^2 r$ by $kL_0 r$ to get $\dfrac{1}{L_0} - \dfrac{1}{r} = \dfrac{m}{kL_0}\,\omega^2$, so $$\frac{1}{r} = \frac{1}{L_0} - \frac{m}{kL_0}\,\omega^2.$$ A graph of $\dfrac{1}{r}$ (vertical) versus $\omega^2$ (horizontal) is a straight line with slope $-\dfrac{m}{kL_0}$ and vertical intercept $\dfrac{1}{L_0}$. The spring constant is $k = \dfrac{m}{L_0\,|\text{slope}|}$.` },
  { id: "p2c-f1cii", type: "frq", skill: "u2", topic: "2.9", set: "p2c-s17", part: "(c)(ii)",
    prompt: E`The student collects the data shown in the table in the problem statement. Use the blank grid provided to plot the data and draw the best-fit line. Calculate any quantity you need that is not in the table, and include it in your graph. Label the axes with the quantities and units, and choose a scale that uses more than half of each axis.`,
    rows: [{ name: "Axes and scale", earns: E`Labels the axes with $\dfrac{1}{r}$ (in m$^{-1}$) and $\omega^2$ (in rad$^2$/s$^2$) and chooses a linear scale that uses more than half of the length of each axis.` },
      { name: "Points and line", earns: E`Plots the five points correctly, at $\omega^2 = 16, 36, 64, 100, 144$ and $\dfrac{1}{r} = 9.2, 8.2, 6.8, 5.0, 2.8$ m$^{-1}$, and draws a straight best-fit line that passes close to the points.` }],
    solution: E`Compute $\omega^2$ (rad$^2$/s$^2$): $16$, $36$, $64$, $100$, $144$, and $\dfrac{1}{r}$ with $r$ in meters (m$^{-1}$): $9.2$, $8.2$, $6.8$, $5.0$, $2.8$. Plot $\dfrac{1}{r}$ on the vertical axis, from $0$ to $10$ m$^{-1}$, and $\omega^2$ on the horizontal axis, from $0$ to $150$ rad$^2$/s$^2$. The points lie on a straight line that slopes down, with a vertical intercept near $10$ m$^{-1}$ and a value near $2.8$ m$^{-1}$ at $\omega^2 = 144$ rad$^2$/s$^2$.` },
  { id: "p2c-f1ciii", type: "frq", skill: "u2", topic: "2.9", set: "p2c-s17", part: "(c)(iii)",
    prompt: E`Use the best-fit line to calculate the spring constant $k$.`,
    rows: [{ name: "Spring constant", earns: E`Uses two points on the best-fit line, not data points, to find the slope (about $-0.050$ m$^{-1}$ per rad$^2$/s$^2$), and obtains $k = \dfrac{m}{L_0\,|\text{slope}|}$ between $37$ and $43$ N/m, with units.` }],
    solution: E`Take two points on the line, for example $(0,\ 10.0\ \text{m}^{-1})$ and $(144\ \text{rad}^2/\text{s}^2,\ 2.8\ \text{m}^{-1})$. The slope is $\dfrac{2.8 - 10.0}{144 - 0} = -0.050$ m$^{-1}$ per rad$^2$/s$^2$. Then $k = \dfrac{m}{L_0\,|\text{slope}|} = \dfrac{0.200}{(0.100)(0.050)} = 40$ N/m.` },
];
